import { describe, expect, it } from 'bun:test';
import { mkdtempSync, readFileSync, writeFileSync } from 'fs';
import { tmpdir } from 'os';
import path from 'path';
import {
  setCargoLockPackageVersion,
  syncCargoLockVersion,
} from '../../scripts/cargo-lock-version.mjs';

const repoRoot = path.resolve(import.meta.dir, '../..');
const lock = (version, eol = '\n') =>
  [
    '# This file is automatically @generated by Cargo.',
    'version = 4',
    '',
    '[[package]]',
    'name = "start-command"',
    `version = "${version}"`,
    'dependencies = [',
    ' "serde",',
    ']',
    '',
    '[[package]]',
    'name = "start-command-helper"',
    'version = "9.9.9"',
    '',
  ].join(eol);

describe('setCargoLockPackageVersion', () => {
  it('rewrites only the named package entry', () => {
    const result = setCargoLockPackageVersion(
      lock('0.23.0'),
      'start-command',
      '0.27.0'
    );
    expect(result).toEqual({
      text: lock('0.27.0'),
      found: true,
      changed: true,
    });
    expect(result.text).toContain('version = "9.9.9"');
  });

  it('reports an already synced entry as unchanged', () => {
    expect(
      setCargoLockPackageVersion(lock('0.27.0'), 'start-command', '0.27.0')
    ).toEqual({ text: lock('0.27.0'), found: true, changed: false });
  });

  it('keeps CRLF line endings', () => {
    expect(
      setCargoLockPackageVersion(
        lock('0.1.0', '\r\n'),
        'start-command',
        '0.2.0'
      ).text
    ).toBe(lock('0.2.0', '\r\n'));
  });

  it('does not match a package whose name only starts with the crate name', () => {
    expect(
      setCargoLockPackageVersion(lock('0.1.0'), 'start', '1.0.0').found
    ).toBe(false);
  });
});

describe('syncCargoLockVersion', () => {
  it('writes the file only when the version changes', () => {
    const file = path.join(mkdtempSync(path.join(tmpdir(), 'lock-')), 'l');
    writeFileSync(file, lock('0.1.0'));
    expect(syncCargoLockVersion(file, 'start-command', '0.2.0')).toBe(true);
    expect(readFileSync(file, 'utf8')).toBe(lock('0.2.0'));
    expect(syncCargoLockVersion(file, 'start-command', '0.2.0')).toBe(false);
  });

  it('skips a missing lock file and rejects a lock without the crate', () => {
    const dir = mkdtempSync(path.join(tmpdir(), 'lock-'));
    expect(
      syncCargoLockVersion(path.join(dir, 'none'), 'start-command', '1.0.0')
    ).toBe(false);
    const file = path.join(dir, 'Cargo.lock');
    writeFileSync(file, lock('0.1.0'));
    expect(() => syncCargoLockVersion(file, 'other', '1.0.0')).toThrow(
      /no \[\[package\]\] entry for other/
    );
  });
});

describe('repository Cargo.lock (issue #234)', () => {
  it('records the Cargo.toml version of the crate', () => {
    const manifest = readFileSync(
      path.join(repoRoot, 'rust/Cargo.toml'),
      'utf8'
    );
    const name = manifest.match(/^name\s*=\s*"([^"]+)"/m)[1];
    const version = manifest.match(/^version\s*=\s*"([^"]+)"/m)[1];
    const result = setCargoLockPackageVersion(
      readFileSync(path.join(repoRoot, 'rust/Cargo.lock'), 'utf8'),
      name,
      version
    );
    expect(result.found).toBe(true);
    expect(result.changed).toBe(false);
  });

  it('is synced and staged by both Rust version bump scripts', () => {
    for (const script of ['version-and-commit.mjs', 'bump-version.mjs']) {
      const source = readFileSync(
        path.join(repoRoot, 'scripts', script),
        'utf8'
      );
      expect(source).toContain("syncCargoLockVersion('Cargo.lock'");
    }
    expect(
      readFileSync(
        path.join(repoRoot, 'scripts/version-and-commit.mjs'),
        'utf8'
      )
    ).toContain("['Cargo.toml', 'Cargo.lock', 'CHANGELOG.md', 'changelog.d']");
  });
});
